const t='<i class="bi bi-check2 me-1"></i>Copied';export function initCopyIcons(){const n=document.querySelectorAll(".copyIcon");Array.from(n).forEach(n=>{n.addEventListener("click",n=>{const o=n.currentTarget.dataset.copydata;navigator.clipboard.writeText(o),n.currentTarget.innerHTML=t})})}export function lockButtonWidth(t,n){const o=t.innerHTML;t.innerHTML=n,t.style.minWidth=t.offsetWidth+"px",t.innerHTML=o}export function lockCopyButtonWidth(n){lockButtonWidth(n,t)}export function copyString(n,o){navigator.clipboard.writeText(o),n.forEach(n=>{n.disabled=!0;const o=n.innerHTML;n.innerHTML=t,setTimeout(()=>{n.innerHTML=o,n.disabled=!1},4e3)})}